import sys

def generate_grid(A, B):
    if A == 1 and B == 1:
        return "1 1\n#"

    if A == 1:
        return f"{B + 1} {B + 1}\n{'#' * (B + 1)}\n{'.' * (B + 1)}" * B

    if B == 1:
        return f"{A + 1} {A + 1}\n{'.' * (A + 1)}\n{'#' * (A + 1)}" * A

    h = A + B + 1
    w = A + B + 1

    grid = [['.' for _ in range(w)] for _ in range(h)]

    def fill_white(x, y, color):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if 0 <= cx < h and 0 <= cy < w and grid[cx][cy] == '.':
                grid[cx][cy] = '#' if color else '.'
                stack.extend([(cx + dx, cy + dy) for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]])

    def place_components(num_components, color):
        nonlocal h, w
        while num_components > 0:
            x, y = 0, 0
            while 0 <= x < h and 0 <= y < w and grid[x][y] != '.':
                x += 1
                if x >= h:
                    x = 0
                    y += 1
            fill_white(x, y, color)
            num_components -= 1

    place_components(A, False)
    place_components(B, True)

    return f"{h} {w}\n" + '\n'.join(''.join(row) for row in grid)

