def generate_grid(A, B):
    if A > B:
        A, B = B, A

    def split_into_components(grid, num_components):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        visited = set()

        def dfs(x, y):
            stack = [(x, y)]
            while stack:
                cx, cy = stack.pop()
                if (cx, cy) in visited:
                    continue
                visited.add((cx, cy))
                for dx, dy in directions:
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                        stack.append((nx, ny))

        components = []
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == '.' and (i, j) not in visited:
                    components.append([])
                    dfs(i, j)
                    components[-1].append((i, j))

        return components

    h, w = A * 2 + 1, B * 2 + 1
    grid = [['#' for _ in range(w)] for _ in range(h)]

    white_components = split_into_components(grid, A)
    black_components = split_into_components([[grid[i][j] if grid[i][j] != '#' else '.' for j in range(w)] for i in range(h)], B)

    def place_components(components):
        for comp in components:
            for x, y in comp:
                grid[x][y] = '.'

    place_components(white_components)
    place_components(black_components)

